import React, { useState, useEffect } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { useForm } from 'react-hook-form';
import { useAuth } from '../contexts/AuthContext';
import { Heart, ArrowLeft, Calendar, MapPin, Package, Truck, Download } from 'lucide-react';
import toast from 'react-hot-toast';

const DonationForm = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const { api } = useAuth();
  const [orphanages, setOrphanages] = useState([]);
  const [loading, setLoading] = useState(false);
  const [selectedOrphanage, setSelectedOrphanage] = useState(null);

  // Get pre-selected category and subcategory from navigation state
  const { selectedCategory, selectedSubcategory, selectedOrphanage: preSelectedOrphanage } = location.state || {};

  const {
    register,
    handleSubmit,
    watch,
    setValue,
    formState: { errors },
  } = useForm({
    defaultValues: {
      category: selectedCategory || '',
      subcategory: selectedSubcategory || '',
      quantity: 1,
      unit: '',
      deliveryMethod: 'dropoff',
      preferredDeliveryDate: '',
    }
  });

  const watchedCategory = watch('category');
  const watchedDeliveryMethod = watch('deliveryMethod');

  // Fetch orphanages on component mount
  useEffect(() => {
    fetchOrphanages();
  }, []);

  // Set pre-selected orphanage if available
  useEffect(() => {
    if (preSelectedOrphanage) {
      setSelectedOrphanage(preSelectedOrphanage);
      setValue('orphanage', preSelectedOrphanage._id);
    }
  }, [preSelectedOrphanage, setValue]);

  const fetchOrphanages = async () => {
    try {
      const response = await api.get('/orphanages?verified=true&limit=100');
      setOrphanages(response.data.orphanages);
    } catch (error) {
      console.error('Failed to fetch orphanages:', error);
      toast.error('Failed to load orphanages');
    }
  };

  const onSubmit = async (data) => {
    if (!selectedOrphanage) {
      toast.error('Please select an orphanage');
      return;
    }

    setLoading(true);
    try {
      const donationData = {
        ...data,
        orphanage: selectedOrphanage._id,
        preferredDeliveryDate: new Date(data.preferredDeliveryDate).toISOString(),
      };

      const response = await api.post('/donations', donationData);

      if (response.data.success) {
        toast.success('Donation request submitted successfully!');
        navigate('/donations');
      }
    } catch (error) {
      console.error('Failed to submit donation:', error);
      const message = error.response?.data?.error || 'Failed to submit donation request';
      toast.error(message);
    } finally {
      setLoading(false);
    }
  };

  // Category configurations
  const categories = {
    food: {
      label: 'Food',
      subcategories: ['Plate Meals', 'Bulk Items', 'Raw Items', 'Processed Items'],
      units: ['plates', 'kg', 'packets', 'boxes', 'pieces']
    },
    clothes: {
      label: 'Clothes',
      subcategories: ['Men', 'Women', 'Kids'],
      units: ['sets', 'pieces', 'pairs', 'kg']
    },
    education: {
      label: 'Education',
      subcategories: ['Stationary', 'Bags', 'Essentials'],
      units: ['pieces', 'sets', 'boxes', 'kg']
    },
    medical: {
      label: 'Medical',
      subcategories: ['Cotton', 'Tapes', 'Scissors', 'Dettol'],
      units: ['pieces', 'rolls', 'pairs', 'bottles', 'boxes']
    },
    money: {
      label: 'Money',
      subcategories: ['UPI Donation'],
      units: ['INR']
    },
    hygiene: {
      label: 'Hygiene',
      subcategories: ['Brushing Essentials', 'Soap', 'Skin Care', 'Bathroom Amenities'],
      units: ['pieces', 'sets', 'bottles', 'tubes']
    }
  };

  const getCurrentCategory = () => categories[watchedCategory] || {};

  return (
    <div className="max-w-4xl mx-auto space-y-6">
      {/* Header */}
      <div className="flex items-center space-x-4">
        <button
          onClick={() => navigate(-1)}
          className="p-2 hover:bg-secondary-100 rounded-lg transition-colors"
        >
          <ArrowLeft className="w-5 h-5" />
        </button>
        <div>
          <h1 className="text-3xl font-bold text-secondary-900">Make a Donation</h1>
          <p className="text-secondary-600">Help make a difference in children's lives</p>
        </div>
      </div>

      {/* Form */}
      <div className="card">
        <form onSubmit={handleSubmit(onSubmit)} className="space-y-6">
          {/* Orphanage Selection */}
          <div>
            <label className="block text-sm font-medium text-secondary-700 mb-2">
              Select Orphanage *
            </label>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              {orphanages.map((orphanage) => (
                <div
                  key={orphanage._id}
                  className={`p-4 border-2 rounded-lg cursor-pointer transition-all duration-200 ${
                    selectedOrphanage?._id === orphanage._id
                      ? 'border-primary-500 bg-primary-50'
                      : 'border-secondary-200 hover:border-primary-300'
                  }`}
                  onClick={() => setSelectedOrphanage(orphanage)}
                >
                  <div className="flex items-center space-x-3">
                    <div className="w-10 h-10 bg-primary-100 rounded-lg flex items-center justify-center">
                      <Heart className="w-5 h-5 text-primary-600" />
                    </div>
                    <div className="flex-1 min-w-0">
                      <h3 className="font-medium text-secondary-900 truncate">
                        {orphanage.name}
                      </h3>
                      <p className="text-sm text-secondary-600 truncate">
                        {orphanage.address.city}, {orphanage.address.state}
                      </p>
                    </div>
                  </div>
                </div>
              ))}
            </div>
            {!selectedOrphanage && (
              <p className="mt-2 text-sm text-error-600">Please select an orphanage</p>
            )}
          </div>

          {/* Category and Subcategory */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <label className="block text-sm font-medium text-secondary-700 mb-2">
                Category *
              </label>
              <select
                {...register('category', { required: 'Category is required' })}
                className="input-field"
              >
                <option value="">Select a category</option>
                {Object.entries(categories).map(([key, category]) => (
                  <option key={key} value={key}>
                    {category.label}
                  </option>
                ))}
              </select>
              {errors.category && (
                <p className="mt-1 text-sm text-error-600">{errors.category.message}</p>
              )}
            </div>

            <div>
              <label className="block text-sm font-medium text-secondary-700 mb-2">
                Subcategory *
              </label>
              <select
                {...register('subcategory', { required: 'Subcategory is required' })}
                className="input-field"
                disabled={!watchedCategory}
              >
                <option value="">Select a subcategory</option>
                {watchedCategory && categories[watchedCategory]?.subcategories.map((sub) => (
                  <option key={sub} value={sub}>
                    {sub}
                  </option>
                ))}
              </select>
              {errors.subcategory && (
                <p className="mt-1 text-sm text-error-600">{errors.subcategory.message}</p>
              )}
            </div>
          </div>

          {/* Quantity and Unit */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <label className="block text-sm font-medium text-secondary-700 mb-2">
                Quantity *
              </label>
              <input
                type="number"
                min="1"
                {...register('quantity', {
                  required: 'Quantity is required',
                  min: { value: 1, message: 'Quantity must be at least 1' }
                })}
                className="input-field"
                placeholder="Enter quantity"
              />
              {errors.quantity && (
                <p className="mt-1 text-sm text-error-600">{errors.quantity.message}</p>
              )}
            </div>

            <div>
              <label className="block text-sm font-medium text-secondary-700 mb-2">
                Unit *
              </label>
              <select
                {...register('unit', { required: 'Unit is required' })}
                className="input-field"
              >
                <option value="">Select unit</option>
                {getCurrentCategory().units?.map((unit) => (
                  <option key={unit} value={unit}>
                    {unit}
                  </option>
                ))}
              </select>
              {errors.unit && (
                <p className="mt-1 text-sm text-error-600">{errors.unit.message}</p>
              )}
            </div>
          </div>

          {/* Description */}
          <div>
            <label className="block text-sm font-medium text-secondary-700 mb-2">
              Description
            </label>
            <textarea
              {...register('description')}
              rows="3"
              className="input-field"
              placeholder="Provide additional details about your donation..."
            />
          </div>

          {/* Delivery Method */}
          <div>
            <label className="block text-sm font-medium text-secondary-700 mb-2">
              Delivery Method *
            </label>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              {[
                { value: 'dropoff', label: 'Drop Off', icon: Package },
                { value: 'pickup', label: 'Pickup', icon: Truck },
                { value: 'delivery', label: 'Delivery', icon: MapPin }
              ].map((method) => {
                const Icon = method.icon;
                return (
                  <label
                    key={method.value}
                    className={`flex items-center space-x-3 p-4 border-2 rounded-lg cursor-pointer transition-all duration-200 ${
                      watchedDeliveryMethod === method.value
                        ? 'border-primary-500 bg-primary-50'
                        : 'border-secondary-200 hover:border-primary-300'
                    }`}
                  >
                    <input
                      type="radio"
                      value={method.value}
                      {...register('deliveryMethod', { required: 'Delivery method is required' })}
                      className="sr-only"
                    />
                    <Icon className="w-5 h-5 text-primary-600" />
                    <span className="font-medium">{method.label}</span>
                  </label>
                );
              })}
            </div>
            {errors.deliveryMethod && (
              <p className="mt-1 text-sm text-error-600">{errors.deliveryMethod.message}</p>
            )}
          </div>

          {/* Delivery Date */}
          <div>
            <label className="block text-sm font-medium text-secondary-700 mb-2">
              Preferred Delivery Date *
            </label>
            <div className="relative">
              <Calendar className="absolute left-3 top-1/2 transform -translate-y-1/2 w-5 h-5 text-secondary-400" />
              <input
                type="date"
                {...register('preferredDeliveryDate', {
                  required: 'Delivery date is required',
                  validate: (value) => {
                    const selectedDate = new Date(value);
                    const today = new Date();
                    today.setHours(0, 0, 0, 0);
                    return selectedDate >= today || 'Delivery date must be today or in the future';
                  }
                })}
                className="input-field pl-10"
                min={new Date().toISOString().split('T')[0]}
              />
            </div>
            {errors.preferredDeliveryDate && (
              <p className="mt-1 text-sm text-error-600">{errors.preferredDeliveryDate.message}</p>
            )}
          </div>

          {/* Notes */}
          <div>
            <label className="block text-sm font-medium text-secondary-700 mb-2">
              Additional Notes
            </label>
            <textarea
              {...register('notes')}
              rows="3"
              className="input-field"
              placeholder="Any special instructions or notes for the orphanage..."
            />
          </div>

          {/* Submit Button */}
          <div className="flex justify-end space-x-4">
            <button
              type="button"
              onClick={() => navigate(-1)}
              className="btn-outline"
            >
              Cancel
            </button>
            <button
              type="submit"
              disabled={loading || !selectedOrphanage}
              className="btn-primary flex items-center space-x-2"
            >
              {loading ? (
                <>
                  <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white"></div>
                  <span>Submitting...</span>
                </>
              ) : (
                <>
                  <Heart className="w-4 h-4" />
                  <span>Submit Donation</span>
                </>
              )}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default DonationForm;
